+    /// Every two-way char-boundary split of `text`.
+    fn two_way_splits(text: &str) -> Vec<(String, String)> {
+        text.char_indices()
+            .map(|(index, _)| index)
+            .chain([text.len()])
+            .map(|index| (text[..index].to_string(), text[index..].to_string()))
+            .collect()
